    @SuppressLint("UnspecifiedRegisterReceiverFlag")
    @Override protected void onStart(){super.onStart();if(!initialized)return;IntentFilter filter=new IntentFilter(MonitorService.ACTION_UPDATE);if(Build.VERSION.SDK_INT>=33)registerReceiver(receiver,filter,Context.RECEIVER_NOT_EXPORTED);else registerReceiver(receiver,filter);refreshHistory();refreshFitness();startHeartPulse();startService(new Intent(this,MonitorService.class).setAction(MonitorService.ACTION_STATUS));}
    @Override protected void onStop(){try{unregisterReceiver(receiver);}catch(Exception ignored){}if(heartPulse!=null)heartPulse.cancel();super.onStop();}

    @Override protected void onDestroy(){insightsWorker.shutdown();if(timeline!=null)timeline.close();super.onDestroy();}
