    private LinearLayout fold(String title,View content){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);Button toggle=outlineButton(title+"  +");box.addView(toggle,lp(-1,dp(56),0,0,0,0));content.setVisibility(View.GONE);box.addView(content);toggle.setOnClickListener(v->{boolean show=content.getVisibility()!=View.VISIBLE;content.setVisibility(show?View.VISIBLE:View.GONE);toggle.setText(title+(show?"  −":"  +"));});return box;}

    private void refreshFitness(){
        if(fitnessState==null||insightsWorker.isShutdown())return;int revision=++fitnessRevision;insightsWorker.execute(()->{FitnessInsights.Summary s=FitnessInsights.summarize(this);List<FitnessInsights.Morning> mornings=FitnessInsights.mornings(this);AdaptiveTwin.Report twin=AdaptiveTwin.analyze(this,s);runOnUiThread(()->{if(!isDestroyed()&&revision==fitnessRevision)applyFitness(s,mornings,twin);});});
    }
    private void applyFitness(FitnessInsights.Summary s,List<FitnessInsights.Morning> mornings,AdaptiveTwin.Report twin){
        SportsPanel.populate(this,sportsPanel,this::refreshFitness);
        fitnessState.setText(s.state);fitnessStateDetail.setText(s.hasToday?"Réponse personnelle du jour • pas un diagnostic":s.stateDetail);fitnessScore.setText(twin.reliable?"Suivi":"Repères");fitnessConfidence.setText(twin.stage+" • "+s.totalMornings+" bilan(s)");
        int stateColor=s.state.contains("inhabituel")||s.state.contains("réduite")?RED:s.state.contains("Charge")?AMBER:TEAL;fitnessState.setTextColor(stateColor);homeFitnessState.setText(s.state);homeFitnessState.setTextColor(stateColor);homeFitnessDetail.setText(s.hasToday?"Ton bilan et tes tendances sont disponibles.":"Trois minutes au calme pour préparer ton bilan.");
        twinDose.setText(twin.doseLow==0&&twin.doseHigh==0?twin.doseTitle:twin.doseLow+"–"+twin.doseHigh+" min équivalentes");twinDoseDetail.setText(twin.doseDetail);twinForecast.setText(twin.forecast);twinInterval.setText(twin.interval.isEmpty()?"Les estimations apparaissent quand les données le permettent.":twin.interval);
        FitnessInsights.Morning current=s.hasToday?s.current:null;fitnessRestingHr.setText(current!=null?String.format(Locale.FRANCE,"%.0f bpm",current.restingHr):s.baselineHr>0?String.format(Locale.FRANCE,"réf. %.0f",s.baselineHr):"--");fitnessRmssd.setText(current!=null?String.format(Locale.FRANCE,"%.0f ms",current.rmssd):s.baselineRmssd>0?String.format(Locale.FRANCE,"réf. %.0f",s.baselineRmssd):"--");fitnessTrend.setText(s.totalMornings<4?"--":String.format(Locale.FRANCE,"%+.0f %%",s.hrvTrendPercent));
        fitnessWhy.removeAllViews();for(String item:twin.factors)fitnessWhy.addView(infoLine("●",item,BLUE));
        twinDrivers.removeAllViews();for(AdaptiveTwin.Driver d:twin.drivers){String detail=d.interpretation+" • "+d.exposed+" avec / "+d.control+" sans";twinDrivers.addView(infoLine(d.usable?d.effect<-.35?"↓":d.effect>.35?"↑":"≈":"…",d.name+" — "+detail,d.usable?d.effect<-.35?RED:TEAL:MUTED));}twinExperiment.setText(twin.experiment);AdaptiveTwin.ExperimentState experiment=AdaptiveTwin.experiment(this);twinExperimentAction.setText(experiment.active?"Terminer cette expérience":"Tester un coucher 30 min plus tôt");
        twinModelStage.setText(twin.stage);twinModelStage.setTextColor(twin.reliable?TEAL:twin.samples>=21?AMBER:BLUE);twinLearningProgress.setProgress(Math.min(30,twin.samples));String performance=twin.evaluated==0?"Pas encore de journée testable":String.format(Locale.FRANCE,"Erreur ML %.2f • référence naïve %.2f • %d prévision(s) testée(s)",twin.modelMae,twin.naiveMae,twin.evaluated);twinModelMetrics.setText(twin.samples+" transition(s) apprises • "+performance);fitnessAdvice.removeAllViews();fitnessAdvice.addView(infoLine(twin.reliable?"✓":"○",twin.status,twin.reliable?TEAL:AMBER));
        fitnessProfileLabel.setText(s.profile.complete()?(s.profile.sport.isEmpty()?"Contexte enregistré":s.profile.sport)+(!s.profile.goal.isEmpty()?" • "+s.profile.goal:""):"Profil à compléter");fitnessAdaptationProgress.setProgress(s.adaptationScore);if(s.profile.complete()){String context="Âge : zones estimées"+(s.profile.hrMedication?" suspendues (traitement déclaré)":"")+" • IMC contextuel : "+String.format(Locale.FRANCE,"%.1f",s.profile.bmi())+"\nL’activité et le ressenti complètent les mesures.";if(!s.profile.sex.isEmpty())context+="\nSexe : "+s.profile.sex+" — contexte facultatif, aucun bonus ou malus quotidien";fitnessProfileDetail.setText(context);}else fitnessProfileDetail.setText("Complète les informations essentielles pour contextualiser les zones et le démarrage. Le modèle personnel prendra ensuite le relais.");
        fitnessModerate.setText(s.observedModerate+" min");fitnessVigorous.setText(s.observedVigorous+" min");fitnessStrength.setText(s.profile.complete()?s.profile.strengthDays+" j déclarés":"À renseigner");fitnessActivityProgress.setProgress(Math.min(150,s.observedModerate+2*s.observedVigorous));fitnessTrendView.setValues(mornings);SessionHistory.Record unrated=AdaptiveTwin.latestSessionToRate(this);twinTrainingStatus.setText(unrated==null?"Toutes les séances récentes sont renseignées.":"Séance du "+new SimpleDateFormat("dd/MM à HH:mm",Locale.FRANCE).format(new Date(unrated.startMs))+" • "+duration(unrated.endMs-unrated.startMs));twinTrainingAction.setEnabled(unrated!=null);twinTrainingAction.setAlpha(unrated==null?.45f:1f);
        fitnessMorningProgress.setProgress(morningActive?morningProgress:s.hasToday?100:0);fitnessMorningAction.setText(morningActive?"Annuler le bilan":s.hasToday?"Refaire le bilan du jour":"Lancer le bilan de 3 minutes");
        if(morningActive)fitnessMorningStatus.setText(morningMessage.isEmpty()?"Mesure en cours…":morningMessage);else if(!morningMessage.isEmpty())fitnessMorningStatus.setText(morningMessage);else fitnessMorningStatus.setText(s.hasToday?"Bilan d’aujourd’hui enregistré • signal "+String.format(Locale.FRANCE,"%.0f %%",s.current.quality):"Aucun bilan enregistré aujourd’hui.");
    }

    private void showSessionRatingDialog(){
        SessionHistory.Record session=AdaptiveTwin.latestSessionToRate(this);if(session==null){Toast.makeText(this,"Aucune séance récente en attente.",Toast.LENGTH_SHORT).show();return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(18),dp(8),dp(18),dp(8));form.addView(text("À quel point cette séance a-t-elle été difficile ?",13,TEXT,true));form.addView(text("1 = très facile • 10 = effort maximal. Cette note ajuste la charge que le modèle relie au bilan du lendemain.",11,MUTED,false),lp(-1,-2,0,5,0,8));EditText rpe=formInput("Effort perçu de 1 à 10",5,true);form.addView(rpe,lp(-1,dp(50),0,4,0,7));CheckBox completed=styledCheck("Séance terminée comme prévu",true);form.addView(completed);
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Retour sur la séance").setView(form).setNegativeButton("Plus tard",null).setPositiveButton("Enregistrer",null).create();dialog.setOnShowListener(ignored->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{int value=intValue(rpe);if(value<1||value>10){Toast.makeText(this,"Choisis une valeur entre 1 et 10.",Toast.LENGTH_LONG).show();return;}AdaptiveTwin.saveSessionRating(this,session.startMs,value,completed.isChecked());dialog.dismiss();refreshFitness();Toast.makeText(this,"Le modèle utilisera ce retour au prochain apprentissage.",Toast.LENGTH_SHORT).show();}));dialog.show();
    }

    private void toggleTwinExperiment(){AdaptiveTwin.ExperimentState state=AdaptiveTwin.experiment(this);if(state.active)new AlertDialog.Builder(this).setTitle("Terminer l’expérience ?").setMessage("Les observations déjà enregistrées restent dans les bilans, mais aucun nouveau matin ne sera ajouté à ce test.").setNegativeButton("Continuer",null).setPositiveButton("Terminer",(d,w)->{AdaptiveTwin.stopExperiment(this);refreshFitness();}).show();else new AlertDialog.Builder(this).setTitle("Tester un coucher plus tôt").setMessage("Pendant environ 12 nuits, essaie certains soirs de te coucher 30 minutes plus tôt. Chaque matin, indique simplement si tu as respecté l’objectif. Le résultat restera masqué tant qu’il n’existe pas assez de journées dans les deux groupes.\n\nCe test observe une association personnelle, pas une preuve médicale.").setNegativeButton("Annuler",null).setPositiveButton("Commencer",(d,w)->{AdaptiveTwin.startSleepExperiment(this);refreshFitness();Toast.makeText(this,"L’expérience commence ce soir.",Toast.LENGTH_LONG).show();}).show();}

    private void showProfileDialog(){ProfileWizard.show(this,this::refreshFitness);}

    private void showMorningDialog(){
        if(!FitnessInsights.profile(this).complete()){Toast.makeText(this,"Complète d’abord ton profil.",Toast.LENGTH_LONG).show();showProfileDialog();return;}if(!streaming){Toast.makeText(this,"Démarre l’enregistrement et attends que le signal soit indiqué comme bon.",Toast.LENGTH_LONG).show();return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(18),dp(8),dp(18),dp(8));form.addView(text("Renseigne le contexte avant de rester immobile et de respirer naturellement.",12,MUTED,false),lp(-1,-2,0,0,0,8));EditText sleep=formInput("Qualité du sommeil de 1 à 5",3,true),stress=formInput("Stress de 1 à 5",3,true),soreness=formInput("Fatigue musculaire de 1 à 5",3,true);form.addView(sleep,lp(-1,dp(50),0,5,0,5));form.addView(stress,lp(-1,dp(50),0,5,0,5));form.addView(soreness,lp(-1,dp(50),0,5,0,5));CheckBox symptoms=styledCheck("J’ai des symptômes inhabituels",false),alcohol=styledCheck("Alcool consommé récemment",false),hard=styledCheck("Séance difficile dans les dernières 24 h",false);form.addView(symptoms);form.addView(alcohol);form.addView(hard);AdaptiveTwin.ExperimentState experiment=AdaptiveTwin.experiment(this);CheckBox experimentFollowed=styledCheck("Hier : objectif « coucher 30 min plus tôt » respecté",false);if(experiment.active){form.addView(text("Expérience personnelle",12,TEAL,true),lp(-1,-2,0,10,0,0));form.addView(experimentFollowed);}
        ScrollView morningScroll=new ScrollView(this);morningScroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Préparer le bilan matinal").setView(morningScroll).setNegativeButton("Annuler",null).setPositiveButton("Commencer",null).create();dialog.setOnShowListener(ignored->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{int sl=intValue(sleep),st=intValue(stress),so=intValue(soreness);if(sl<1||sl>5||st<1||st>5||so<1||so>5){Toast.makeText(this,"Les trois notes doivent être comprises entre 1 et 5.",Toast.LENGTH_LONG).show();return;}Intent intent=new Intent(this,MonitorService.class).setAction(MonitorService.ACTION_START_MORNING).putExtra("sleep",sl).putExtra("stress",st).putExtra("soreness",so).putExtra("symptoms",symptoms.isChecked()).putExtra("alcohol",alcohol.isChecked()).putExtra("hardTraining",hard.isChecked()).putExtra("experimentId",experiment.active?experiment.id:"").putExtra("experimentFollowed",experiment.active&&experimentFollowed.isChecked());startService(intent);morningActive=true;morningProgress=0;morningMessage="Stabilisation de la mesure…";refreshFitness();dialog.dismiss();}));dialog.show();
    }

    private EditText formInput(String hint,int value,boolean numeric){return formInput(hint,value==0?"":String.valueOf(value),numeric);}
    private EditText formInput(String hint,String value,boolean numeric){EditText field=new EditText(this);field.setHint(hint);field.setHintTextColor(MUTED);field.setTextColor(TEXT);field.setText(value);field.setTextSize(13);field.setSingleLine(true);field.setPadding(dp(13),0,dp(13),0);field.setBackground(round(CARD_ALT,LINE,13));if(numeric)field.setInputType(InputType.TYPE_CLASS_NUMBER);return field;}
    private CheckBox styledCheck(String label,boolean checked){CheckBox box=new CheckBox(this);box.setText(label);box.setTextColor(TEXT);box.setTextSize(12);box.setChecked(checked);box.setButtonTintList(new ColorStateList(new int[][]{new int[]{android.R.attr.state_checked},new int[]{}},new int[]{TEAL,MUTED}));return box;}
    private void addProfileField(LinearLayout form,String label,String help,EditText field){form.addView(text(label,12,TEXT,true),lp(-1,-2,0,12,0,3));form.addView(text(help,10,MUTED,false));form.addView(field,lp(-1,dp(50),0,6,0,0));}
    private void styleChoices(Button[] buttons,String[] values,String selected){for(int i=0;i<buttons.length;i++){boolean active=values[i].equals(selected);buttons[i].setTextColor(active?0xff06251f:MUTED);buttons[i].setBackground(ripple(active?TEAL:CARD_ALT,active?TEAL:LINE,13));}}
    private int intValue(EditText field){try{return Integer.parseInt(field.getText().toString().trim());}catch(Exception ignored){return 0;}}
    private View infoLine(String icon,String value,int color){LinearLayout line=row();TextView mark=text(icon,13,color,true);line.addView(mark,lp(dp(22),-2,0,0,5,0));line.addView(text(value,12,MUTED,false),new LinearLayout.LayoutParams(0,-2,1));line.setPadding(0,dp(10),0,0);return line;}
    private void confirmFitnessReset(){if(running){Toast.makeText(this,"Arrête l’enregistrement avant de remettre le suivi à zéro.",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Réinitialiser le suivi de forme ?").setMessage("Le profil, les bilans matinaux, les coefficients appris et les prévisions seront supprimés. Les ECG, rapports et événements resteront disponibles.").setNegativeButton("Annuler",null).setPositiveButton("Effacer",(dialog,which)->{insightsWorker.execute(()->{FitnessInsights.clear(this);AdaptiveTwin.clear(this);TrainingJournal.clear(this);runOnUiThread(()->{morningMessage="";refreshFitness();Toast.makeText(this,"Suivi de forme remis à zéro.",Toast.LENGTH_SHORT).show();});});}).show();}

