    private void buildNavigation(){
        nav=row();nav.setPadding(dp(8),dp(8),dp(8),dp(8));nav.setBackgroundColor(CARD);
        homeTab=navItem("Aujourd’hui");fitnessTab=navItem("ECG");historyTab=navItem("Forme");settingsTab=navItem("Historique");
        TextView[] tabs={homeTab,fitnessTab,historyTab,settingsTab};for(int i=0;i<tabs.length;i++){final int page=i;nav.addView(tabs[i],new LinearLayout.LayoutParams(0,-1,1));tabs[i].setOnClickListener(v->showPage(page));}
    }
    private void showPage(int page){
        currentPage=page;pageHost.removeAllViews();LinearLayout selected=page==0?homePage:page==1?ecgPage:page==2?fitnessPage:page==3?historyPage:settingsPage;
        ViewGroup parent=(ViewGroup)selected.getParent();if(parent!=null)parent.removeView(selected);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.addView(selected);pageHost.addView(scroll,new LinearLayout.LayoutParams(-1,-1));
        TextView[] tabs={homeTab,fitnessTab,historyTab,settingsTab};for(int i=0;i<tabs.length;i++){boolean active=i==page;tabs[i].setTextColor(active?TEAL:MUTED);tabs[i].setBackground(round(active?0xff15332f:0x00000000,0x00000000,14));tabs[i].setSelected(active);}
        if(page==2)refreshFitness();if(page==3)refreshHistory();
    }

    private void refreshHistory(){
        if(timeline!=null){timeline.refresh();today.setText(EventHistory.countToday(this)+" passage(s)");return;}if(historyList==null)return;historyList.removeAllViews();styleHistoryControls();refreshDashboard();List<EventHistory.Record> records=EventHistory.list(this);today.setText(EventHistory.countToday(this)+" passage(s)");String query=historySearch==null?"":historySearch.getText().toString().trim().toLowerCase(Locale.ROOT);long cutoff=historyDays<=0?0:System.currentTimeMillis()-historyDays*86_400_000L;int shown=0;
        for(EventHistory.Record record:records){if(record.timestampMs<cutoff||!matchesFilter(record)||!matchesQuery(record,query))continue;historyList.addView(historyCard(record),lp(-1,-2,0,0,0,12));shown++;}
        if(shown==0){LinearLayout empty=card();TextView icon=text("⌕",34,TEAL,false);icon.setGravity(Gravity.CENTER);empty.addView(icon);TextView title=text(records.isEmpty()?"Rien à signaler pour le moment":"Aucun résultat avec ces filtres",17,TEXT,true);title.setGravity(Gravity.CENTER);empty.addView(title,lp(-1,-2,0,7,0,4));TextView sub=text(records.isEmpty()?"Les passages inhabituels apparaîtront ici avec leur rapport.":"Essaie une autre période, un autre type ou efface la recherche.",13,MUTED,false);sub.setGravity(Gravity.CENTER);empty.addView(sub);historyList.addView(empty,lp(-1,-2,0,0,0,14));}
    }

    private void refreshDashboard(){if(historyStats==null)return;historyStats.removeAllViews();EventHistory.Aggregate events=EventHistory.aggregate(this,historyDays);SessionHistory.Aggregate sessions=SessionHistory.aggregate(this,historyDays);LinearLayout summary=card();summary.addView(text("Vue d’ensemble",18,TEXT,true));summary.addView(text(periodLabel()+" • "+sessions.sessions+" session(s) • "+duration(sessions.durationMs)+" enregistrées",12,MUTED,false),lp(-1,-2,0,5,0,11));LinearLayout first=row();first.addView(dashboardMetric("Passages",String.valueOf(events.total),AMBER),new LinearLayout.LayoutParams(0,dp(72),1));first.addView(dashboardMetric("Battements",String.valueOf(events.premature+events.esa),BLUE),new LinearLayout.LayoutParams(0,dp(72),1));first.addView(dashboardMetric("Pauses",String.valueOf(events.pauses),RED),new LinearLayout.LayoutParams(0,dp(72),1));summary.addView(first);LinearLayout second=row();second.addView(dashboardMetric("FC moyenne",sessions.avgBpm>0?String.format(Locale.FRANCE,"%.0f",sessions.avgBpm):"--",TEAL),new LinearLayout.LayoutParams(0,dp(72),1));second.addView(dashboardMetric("VFC RMSSD",sessions.rmssd>0?String.format(Locale.FRANCE,"%.0f ms",sessions.rmssd):"--",BLUE),new LinearLayout.LayoutParams(0,dp(72),1));second.addView(dashboardMetric("Signal",sessions.signalQuality>0?String.format(Locale.FRANCE,"%.0f %%",sessions.signalQuality):"--",TEAL),new LinearLayout.LayoutParams(0,dp(72),1));summary.addView(second,lp(-1,-2,0,7,0,0));summary.addView(text("La VFC est calculée sur les intervalles propres entre battements normaux. Elle varie avec le repos, l’effort et le contexte ; ce n’est pas un diagnostic.",11,MUTED,false),lp(-1,-2,0,10,0,0));historyStats.addView(summary,lp(-1,-2,0,0,0,12));}

    private View historyCard(EventHistory.Record record){
        LinearLayout card=card();LinearLayout top=row();TextView title=text(publicTitle(record.type,record.title),16,TEXT,true);org.json.JSONObject reportState=LocalRepository.get(this).find("event",record.id);TextView badge=text(record.ready?"PRÊT":reportState!=null&&"failed".equals(reportState.optString("reportState"))?"ÉCHEC":"CRÉATION",10,record.ready?TEAL:AMBER,true);badge.setGravity(Gravity.CENTER);badge.setPadding(dp(9),dp(5),dp(9),dp(5));badge.setBackground(round(record.ready?0xff123a34:0xff3a2d18,record.ready?0xff1e6658:0xff6c5128,30));top.addView(title,new LinearLayout.LayoutParams(0,-2,1));top.addView(badge);card.addView(top);
        card.addView(text(new SimpleDateFormat("EEEE d MMMM • HH:mm:ss",Locale.FRANCE).format(new Date(record.timestampMs)),12,MUTED,false),lp(-1,-2,0,7,0,0));if(record.bpm>0||record.rmssd>0){String metrics=(record.bpm>0?record.bpm+" bpm":"")+(record.rmssd>0?"  •  VFC "+String.format(Locale.FRANCE,"%.0f ms",record.rmssd):"")+(record.signalQuality>0?"  •  signal "+String.format(Locale.FRANCE,"%.0f %%",record.signalQuality):"");card.addView(text(metrics,11,MUTED,false),lp(-1,-2,0,5,0,0));}
        String review="anomaly".equals(record.review)?"Signalé par toi · non confirmé médicalement":"normal".equals(record.review)?"Marqué comme normal":"artifact".equals(record.review)?"Marqué comme artefact":"À vérifier";TextView reviewView=text(review,12,"anomaly".equals(record.review)?RED:"normal".equals(record.review)?TEAL:AMBER,true);card.addView(reviewView,lp(-1,-2,0,6,0,10));
        if(record.ready){LinearLayout reportActions=row();Button report=outlineButton("Ouvrir le PDF");Button share=outlineButton("Partager");reportActions.addView(report,new LinearLayout.LayoutParams(0,dp(44),1));reportActions.addView(share,new LinearLayout.LayoutParams(0,dp(44),1));card.addView(reportActions,lp(-1,-2,0,0,0,9));report.setOnClickListener(v->openReport(record));share.setOnClickListener(v->shareReport(record));}
        else {org.json.JSONObject state=LocalRepository.get(this).find("event",record.id);String detail=state==null?"Passage indisponible":state.optString("reportState").equals("failed")?"Échec de création : "+state.optString("reportError"):"Capture ou création en cours. Environ 30 secondes de contexte après le passage.";card.addView(text(detail,12,MUTED,false),lp(-1,-2,0,0,0,9));if(System.currentTimeMillis()-record.timestampMs>60_000){Button retry=outlineButton("Réessayer la création");card.addView(retry);retry.setOnClickListener(v->{retry.setEnabled(false);new Thread(()->{String result=EventStore.retryReport(this,record.id);runOnUiThread(()->{retry.setEnabled(true);Toast.makeText(this,result,Toast.LENGTH_LONG).show();refreshHistory();});},"retry-report").start();});}}
        Button replay=outlineButton("Revoir le signal et partager les données");card.addView(replay,lp(-1,dp(48),0,0,0,10));replay.setOnClickListener(v->ReplayView.show(this,record));
        LinearLayout actions=row();Button real=smallButton("Inhabituel");Button normal=smallButton("Normal");Button artifact=smallButton("Artefact");actions.addView(real,new LinearLayout.LayoutParams(0,dp(42),1));actions.addView(normal,new LinearLayout.LayoutParams(0,dp(42),1));actions.addView(artifact,new LinearLayout.LayoutParams(0,dp(42),1));card.addView(actions);real.setOnClickListener(v->sendFeedback(record,"anomaly"));normal.setOnClickListener(v->sendFeedback(record,"normal"));artifact.setOnClickListener(v->sendFeedback(record,"artifact"));return card;
    }

    private void sendFeedback(EventHistory.Record record,String label){EventHistory.review(this,record.id,label);if(record.morphology!=null){Intent intent=new Intent(this,MonitorService.class).setAction(MonitorService.ACTION_FEEDBACK);intent.putExtra("label",label);intent.putExtra("morphology",record.morphology);startService(intent);}Toast.makeText(this,"Merci, ton choix a été enregistré.",Toast.LENGTH_SHORT).show();refreshHistory();}
    private void openReport(EventHistory.Record record){Uri uri=EventHistory.findPdf(this,record.id);if(uri==null){Toast.makeText(this,"Le PDF n’est pas encore disponible.",Toast.LENGTH_LONG).show();return;}Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/pdf").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{startActivity(intent);}catch(Exception e){Toast.makeText(this,"Installe un lecteur PDF pour ouvrir le rapport.",Toast.LENGTH_LONG).show();}}
    private void shareReport(EventHistory.Record record){Uri uri=EventHistory.findPdf(this,record.id);if(uri==null){Toast.makeText(this,"Le PDF n’est pas encore disponible.",Toast.LENGTH_LONG).show();return;}Intent share=new Intent(Intent.ACTION_SEND).setType("application/pdf").putExtra(Intent.EXTRA_STREAM,uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(Intent.createChooser(share,"Partager le rapport ECG"));}
    private void openReportsFolder(){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/pdf");try{startActivity(intent);Toast.makeText(this,"Ouvre Documents puis PolarH10Monitor.",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(this,"Dossier : Documents/PolarH10Monitor",Toast.LENGTH_LONG).show();}}
    private void confirmDeleteReports(){if(running){Toast.makeText(this,"Arrête d’abord l’enregistrement pour effectuer un nettoyage complet.",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Effacer tout l’historique ?").setMessage("Cette action supprime définitivement les rapports PDF, les ECG bruts exportés, les signaux continus, les bilans de forme, les séances et les résumés de sessions.\n\nLe profil morphologique personnel est conservé.").setNegativeButton("Annuler",null).setPositiveButton("Effacer définitivement",(dialog,which)->insightsWorker.execute(()->{try{int deleted=EventStore.deleteAllStoredData(this);LocalRepository.get(this).clear("morning");getSharedPreferences("fitness_local_v1",0).edit().remove("mornings_v1").apply();TrainingJournal.clear(this);AdaptiveTwin.clear(this);startService(new Intent(this,MonitorService.class).setAction(MonitorService.ACTION_FEEDBACK));runOnUiThread(()->{resetHistoryViews();refreshHistory();refreshFitness();Toast.makeText(this,"Historique remis à zéro • "+deleted+" fichier(s) supprimé(s).",Toast.LENGTH_LONG).show();});}catch(Exception error){runOnUiThread(()->Toast.makeText(this,"Nettoyage incomplet : certains fichiers restent présents. "+error.getMessage(),Toast.LENGTH_LONG).show());}})).show();}

    private void resetHistoryViews(){today.setText("0 passage");homeBeats.setText("--");homeRmssd.setText("--");homeSdnn.setText("--");homeSignalQuality.setText("--");homeEctopy.setText("0");homePauses.setText("0");sessionSummary.setText("Historique vide. La prochaine session repartira de zéro.");lastEventCount=-1;if(historySearch!=null)historySearch.setText("");}

    private void requestAndStart(){ArrayList<String> need=new ArrayList<>();if(Build.VERSION.SDK_INT>=31){if(checkSelfPermission(Manifest.permission.BLUETOOTH_SCAN)!=PackageManager.PERMISSION_GRANTED)need.add(Manifest.permission.BLUETOOTH_SCAN);if(checkSelfPermission(Manifest.permission.BLUETOOTH_CONNECT)!=PackageManager.PERMISSION_GRANTED)need.add(Manifest.permission.BLUETOOTH_CONNECT);}else if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED)need.add(Manifest.permission.ACCESS_FINE_LOCATION);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)need.add(Manifest.permission.POST_NOTIFICATIONS);if(!need.isEmpty()){pendingStart=true;requestPermissions(need.toArray(new String[0]),PERMISSIONS);}else startMonitor();}
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==PERMISSIONS&&pendingStart){pendingStart=false;boolean ble=true;for(int i=0;i<permissions.length;i++)if((permissions[i].contains("BLUETOOTH")||permissions[i].contains("LOCATION"))&&results[i]!=PackageManager.PERMISSION_GRANTED)ble=false;if(ble)startMonitor();else Toast.makeText(this,"La permission Bluetooth est nécessaire pour trouver la ceinture.",Toast.LENGTH_LONG).show();}}
    private void startMonitor(){startForegroundService(new Intent(this,MonitorService.class).setAction(MonitorService.ACTION_START));status.setText("Connexion en cours…");}
    private void stopMonitor(){startService(new Intent(this,MonitorService.class).setAction(MonitorService.ACTION_STOP));}

    private void update(Intent intent){
        boolean previousMorning=morningActive;String previousMorningMessage=morningMessage;morningActive=intent.getBooleanExtra("morningActive",false);morningProgress=intent.getIntExtra("morningProgress",0);String receivedMorningMessage=intent.getStringExtra("morningMessage");morningMessage=receivedMorningMessage==null?"":receivedMorningMessage;
        running=intent.getBooleanExtra("running",false);streaming=intent.getBooleanExtra("streaming",false);String state=intent.getStringExtra("status");liveBadge.setText(streaming?"● "+intent.getIntExtra("bpm",0)+" bpm":"EN ATTENTE");status.setText(friendlyStatus(state,running,streaming));statusDot.setTextColor(streaming?RED:running?AMBER:MUTED);device.setText(streaming?intent.getStringExtra("device")+" connectée":running?"Connexion automatique en cours":"Aucune ceinture connectée");
        int heartRate=intent.getIntExtra("bpm",0);bpm.setText(heartRate>0?String.valueOf(heartRate):"--");if(ValueAnimator.areAnimatorsEnabled()&&heartRate>0&&heartRate!=lastDisplayedHeartRate){bpm.animate().cancel();bpm.setScaleX(.92f);bpm.setScaleY(.92f);bpm.animate().scaleX(1f).scaleY(1f).setDuration(220).start();}lastDisplayedHeartRate=heartRate;int batteryLevel=intent.getIntExtra("battery",-1);battery.setText(batteryLevel>=0?batteryLevel+" %"+(intent.getBooleanExtra("batteryStale",false)?" · ancien":""):"-- %");boolean good=intent.getBooleanExtra("signalGood",false),moving=intent.getBooleanExtra("motionActive",false),acc=intent.getBooleanExtra("accActive",false);signal.setText(streaming?(moving?"Mouvement détecté":good?(acc?"Bon • capteur mouvement":"Bon"):"Contact/bruit filtré"):"En attente");
        int learned=intent.getIntExtra("modelSamples",0);boolean ready=intent.getBooleanExtra("modelReady",false);int confirmed=intent.getIntExtra("confirmedExamples",0),artifacts=intent.getIntExtra("artifactExamples",0);modelProgress.setProgress(Math.min(learned,MorphologyModel.BASELINE_TARGET));modelState.setText(ready?"Référence personnelle prête • "+learned+" battements"+(confirmed>0?" • "+confirmed+" anomalie(s)":"")+(artifacts>0?" • "+artifacts+" artefact(s) appris":""):"Apprentissage en cours • "+learned+" / "+MorphologyModel.BASELINE_TARGET+" battements propres");
        int classified=intent.getIntExtra("classifiedBeats",0),uncertain=intent.getIntExtra("uncertainBeats",0);modelState.append("\n"+uncertain+" / "+classified+" battements évalués restent indéterminés.");
        int count=intent.getIntExtra("events",0),rejected=intent.getIntExtra("artifactRejected",0),beatTotal=intent.getIntExtra("beats",0);double rmssd=intent.getDoubleExtra("rmssd",0),sdnn=intent.getDoubleExtra("sdnn",0),quality=intent.getDoubleExtra("signalQuality",0);int early=intent.getIntExtra("esv",0)+intent.getIntExtra("esa",0),pauseCount=intent.getIntExtra("pauses",0);
        homeBeats.setText(beatTotal>0?String.valueOf(beatTotal):"--");homeRmssd.setText(rmssd>0?String.format(Locale.FRANCE,"%.0f ms",rmssd):"--");homeSdnn.setText(sdnn>0?String.format(Locale.FRANCE,"%.0f ms",sdnn):"--");homeSignalQuality.setText(quality>0?String.format(Locale.FRANCE,"%.0f %%",quality):"--");homeEctopy.setText(String.valueOf(early));homePauses.setText(String.valueOf(pauseCount));
        String summary=count==0?"Aucun passage enregistré. Cela n’exclut pas une anomalie.":count+" passage(s) enregistré(s) pendant cette session.";if(rejected>0)summary+=" "+rejected+" forme(s) de bruit écartée(s).";sessionSummary.setText(summary);mainAction.setText(running?"Arrêter l’enregistrement":"Démarrer l’enregistrement");ecgAction.setText(mainAction.getText());mainAction.setBackground(ripple(running?0xff2c1b25:TEAL,running?0xff663244:TEAL,16));mainAction.setTextColor(running?0xffff8fa1:0xff06251f);int epoch=intent.getIntExtra("interruptions",0);if(epoch!=lastSignalEpoch){lastSignalEpoch=epoch;ecg.clear();}float[] wave=intent.getFloatArrayExtra("wave");if(wave!=null)ecg.setSamples(wave,intent.getLongExtra("samples",0));long reportReadyAt=intent.getLongExtra("reportReadyAt",0);if(count!=lastEventCount||reportReadyAt!=lastReportReadyAt){lastEventCount=count;lastReportReadyAt=reportReadyAt;refreshHistory();}
        if(fitnessMorningProgress!=null){fitnessMorningProgress.setProgress(morningActive?morningProgress:fitnessMorningProgress.getProgress());fitnessMorningAction.setText(morningActive?"Annuler le bilan":"Lancer le bilan de 3 minutes");if(morningActive)fitnessMorningStatus.setText(morningMessage);}if((previousMorning&&!morningActive)||(!morningActive&&!morningMessage.equals(previousMorningMessage)))refreshFitness();
    }

    private String friendlyStatus(String raw,boolean running,boolean streaming){if(streaming)return "Enregistrement actif";if(!running)return "Enregistrement arrêté";if(raw==null)return "Connexion en cours…";if(raw.contains("Recherche")||raw.contains("Reconnexion"))return "Recherche de la ceinture…";if(raw.contains("préparation")||raw.contains("Commande"))return "Préparation du signal…";return raw;}
    private String publicTitle(String type,String fallback){switch(type){case"ESV":return"Battement ventriculaire possible";case"ESA":return"Battement auriculaire possible";case"PAUSE":return"Pause inhabituelle";case"IRREGULAR":return"Rythme très irrégulier";case"TACHY":case"REGULAR_TACHY":return"Rythme rapide prolongé";case"BRADY":return"Rythme lent prolongé";case"COUPLET":case"WIDE_RUN":return"Plusieurs battements inhabituels";case"BIGEMINY":case"TRIGEMINY":return"Répétition inhabituelle";default:return fallback==null||fallback.isEmpty()?"Passage à vérifier":fallback;}}
    private Button historyPeriodButton(String label,int days){Button b=smallButton(label);b.setTag(days);periodControls.add(b);b.setOnClickListener(v->{historyDays=days;refreshHistory();});return b;}
    private Button historyFilterButton(String label,String filter){Button b=smallButton(label);b.setTag(filter);filterControls.add(b);LinearLayout.LayoutParams p=lp(dp(104),dp(42),0,0,7,0);b.setLayoutParams(p);b.setOnClickListener(v->{historyFilter=filter;refreshHistory();});return b;}
    private void styleHistoryControls(){for(Button b:periodControls){boolean active=((Integer)b.getTag())==historyDays;b.setTextColor(active?0xff06251f:MUTED);b.setBackground(ripple(active?TEAL:CARD_ALT,active?TEAL:LINE,13));}for(Button b:filterControls){boolean active=historyFilter.equals(b.getTag());b.setTextColor(active?TEXT:MUTED);b.setBackground(ripple(active?0xff1a4050:CARD_ALT,active?TEAL:LINE,13));}}
    private boolean matchesFilter(EventHistory.Record r){if("ALL".equals(historyFilter))return true;if("ARTIFACT".equals(historyFilter))return "artifact".equals(r.review);if("PAUSE".equals(historyFilter))return "PAUSE".equals(r.type);if("IRREGULAR".equals(historyFilter))return "IRREGULAR".equals(r.type);if("RATE".equals(historyFilter))return "TACHY".equals(r.type)||"REGULAR_TACHY".equals(r.type)||"BRADY".equals(r.type);return "ESV".equals(r.type)||"ESA".equals(r.type)||"WIDE_PREMATURE".equals(r.type)||"PREMATURE".equals(r.type)||"COUPLET".equals(r.type)||"WIDE_RUN".equals(r.type)||"BIGEMINY".equals(r.type)||"TRIGEMINY".equals(r.type);}
    private boolean matchesQuery(EventHistory.Record r,String q){if(q.isEmpty())return true;String date=new SimpleDateFormat("dd/MM/yyyy HH:mm EEEE MMMM",Locale.FRANCE).format(new Date(r.timestampMs));String hay=(publicTitle(r.type,r.title)+" "+r.detail+" "+date+" "+r.review).toLowerCase(Locale.ROOT);return hay.contains(q);}
    private String periodLabel(){return historyDays==0?"Depuis le début":historyDays==7?"7 derniers jours":"30 derniers jours";}
    private String duration(long ms){long minutes=ms/60_000L;if(minutes<60)return minutes+" min";return String.format(Locale.FRANCE,"%d h %02d",minutes/60,minutes%60);}
    private View dashboardMetric(String label,String value,int color){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(8),dp(9),dp(8),dp(8));box.setBackground(round(CARD_ALT,LINE,12));TextView l=text(label,9,MUTED,true),v=text(value,15,color,true);v.setSingleLine(true);box.addView(l);box.addView(v,lp(-1,-2,0,5,0,0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(72),1);p.setMargins(dp(3),0,dp(3),0);box.setLayoutParams(p);return box;}
    private void openBatterySettings(){try{startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));Toast.makeText(this,"Ouvre Batterie puis sélectionne Sans restriction.",Toast.LENGTH_LONG).show();}catch(Exception ignored){}}
