    private void confirmModelReset(){new AlertDialog.Builder(this).setTitle("Recommencer l’apprentissage ECG ?").setMessage("Le profil morphologique des battements sera supprimé. Adaptive Twin, l’historique et les rapports seront conservés.").setNegativeButton("Annuler",null).setPositiveButton("Recommencer",(dialog,which)->{startService(new Intent(this,MonitorService.class).setAction(MonitorService.ACTION_RESET_MODEL));modelProgress.setProgress(0);modelState.setText("L’apprentissage ECG recommencera avec un signal propre.");Toast.makeText(this,"Modèle ECG personnel réinitialisé.",Toast.LENGTH_SHORT).show();}).show();}

    private void showWelcome(boolean force){SharedPreferences prefs=getSharedPreferences("settings",MODE_PRIVATE);if(!force&&prefs.getBoolean("welcome_v40",false))return;Dialog dialog=new Dialog(this);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(24),dp(24),dp(24),dp(22));content.setBackground(gradient(0xff172738,CARD,0xff315269,24));TextView logo=text("♥",34,RED,true);logo.setGravity(Gravity.CENTER);logo.setBackground(round(0xff351923,0xff6b2c40,18));content.addView(logo,lp(dp(58),dp(58),0,0,0,18));content.addView(text("Bienvenue dans H10 Rhythm Lab",25,TEXT,true));content.addView(text("Un suivi ECG personnel conçu pour rester lisible, même quand l’analyse devient complexe.",14,MUTED,false),lp(-1,-2,0,7,0,12));content.addView(feature("Connecte ta Polar H10","L’application retrouve ensuite automatiquement ta ceinture."));content.addView(feature("Laisse le modèle apprendre","500 battements sélectionnés automatiquement construisent ta référence."));content.addView(feature("Vérifie seulement l’essentiel","Les passages inhabituels et leurs rapports apparaissent dans Historique."));TextView safety=text("Mode laboratoire distinct : aucune alerte cardiaque physique. Les prédictions peuvent être fausses ; ne pas utiliser pour se rassurer.",11,AMBER,false);safety.setPadding(0,dp(16),0,dp(12));content.addView(safety);Button begin=button(force?"Fermer":"Commencer",TEAL,0xff06251f);content.addView(begin,lp(-1,dp(52),0,0,0,0));ScrollView introScroll=new ScrollView(this);introScroll.addView(content);dialog.setContentView(introScroll);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawable(new ColorDrawable(0x00000000));window.setDimAmount(.78f);window.addFlags(android.view.WindowManager.LayoutParams.FLAG_DIM_BEHIND);window.setLayout(-1,-2);}begin.setOnClickListener(v->{prefs.edit().putBoolean("welcome_v40",true).apply();dialog.dismiss();});dialog.setOnShowListener(ignored->{Window shown=dialog.getWindow();if(shown!=null)shown.setLayout(getResources().getDisplayMetrics().widthPixels-dp(28),(int)(getResources().getDisplayMetrics().heightPixels*.82));});dialog.show();}

    private void startHeartPulse(){if(statusDot==null||!ValueAnimator.areAnimatorsEnabled())return;if(heartPulse==null){PropertyValuesHolder sx=PropertyValuesHolder.ofFloat(View.SCALE_X,1f,1.18f,1f,1.10f,1f,1f);PropertyValuesHolder sy=PropertyValuesHolder.ofFloat(View.SCALE_Y,1f,1.18f,1f,1.10f,1f,1f);PropertyValuesHolder alpha=PropertyValuesHolder.ofFloat(View.ALPHA,.78f,1f,.86f,1f,.82f,.78f);heartPulse=ObjectAnimator.ofPropertyValuesHolder(statusDot,sx,sy,alpha);heartPulse.setDuration(1450);heartPulse.setRepeatCount(ValueAnimator.INFINITE);heartPulse.setRepeatMode(ValueAnimator.RESTART);}if(!heartPulse.isStarted())heartPulse.start();}

